/* Deadlock Companion - vanilla JS, no build step, no modules.
 *
 * Data: data/meta.json + one JSON per entity group (heroes, items, abilities,
 * mechanics, glossary) + patches.json + rules.json, all generated by tools/.
 * THIS FILE HAND-WRITES NO GAME PROSE. Every sentence a user reads about an
 * entity comes out of `beginner.{whatItIs,whyItMatters,whenToUseIt}` in the
 * data, which the pipeline merges forward from tools/beginner-notes/. Chrome
 * labels ("Your first 10 minutes", "Starter build") are UI, not game facts.
 *
 * IA (NEW-GAME-TEMPLATE section 8): five tabs - Start / Heroes / Items / Builds /
 * More - a search field on EVERY tab, and every entity sheet carries the same
 * three headings in this order: What it is / Why it matters / When to use it.
 *
 * PORT NOTES (fiiiish-app shell):
 *  - The shell strips #topbar and #siteFoot. Every lookup into either is
 *    null-guarded, so a stripped id is a no-op, not a crash.
 *  - This app owns location.hash -> the registry entry must set
 *    nativeHashRouting: true. The shared shim fires synchronously and would
 *    lose the race against the data fetch.
 *  - No service worker is registered here. The shell owns exactly one. The
 *    block at the bottom of this file only WAITS for whichever worker already
 *    controls the page and posts it the sprite-warm list - that is the app
 *    half of registry.spriteWarm and it must not be removed. Standalone, with
 *    no worker, it no-ops.
 *  - No absolute deploy URL anywhere. All app assets are '/island/apps/deadlock/'-relative or come
 *    from data/*.json as sprites/ paths (registry.assetPrefixes rewrites those).
 *  - The ONLY localStorage key is deadlock_companion_v1 (LS_KEY below). It is
 *    read through a constant, so the registry MUST declare it in syncKeys by
 *    hand. It contains no "token", "auth" or "secret" and does not start with
 *    "sb-" (import.astro's credential filter would silently drop it).
 *
 * ---------------------------------------------------------------------------
 * BUILDS SEAM  (the P4 tool lane plugs in here; the shell never assumes it)
 * ---------------------------------------------------------------------------
 * The Builds tab is composed by renderBuilds() in THIS file as:
 *     search field + FRESHNESS/PATCH STAMP (always shell-rendered, so no tool
 *     can ship without it) + "best found, not a proof" ruling + TOOL BODY.
 * The TOOL BODY is, in order of preference:
 *   1. window.DL_BUILDS.render()  -> an HTML string, if a P4 script registered it
 *      (optional window.DL_BUILDS.afterRender(rootElement) is called after the
 *      shell inserts that HTML, for event wiring on #buildsBody).
 *   2. the shell's own fallback: a per-hero starter-build viewer derived from
 *      data/heroes.json (cheap items most bought by that hero, with sample sizes).
 * P4 scripts load AFTER js/app.js (index.html + registry.scripts, same order)
 * and read the app through window.DL_APP, the stable surface:
 *   DL_APP.S                  state: S.groups.{heroes,items,abilities,mechanics,
 *                             glossary}, S.byId["group:id"], S.meta, S.rules, S.patches
 *   DL_APP.esc / num / pct    formatting
 *   DL_APP.ent(key)           entity by "group:id"
 *   DL_APP.iconHtml(e, size)  local icon markup (44 / 64 / 88)
 *   DL_APP.openEntity(key)    open the detail sheet
 *   DL_APP.prof() / ovGet(p, group, key, dflt) / ovSet(group, key, val) /
 *   DL_APP.saveState()        the active profile + the sparse override layer
 *   DL_APP.loadAnalytics()    memoised Promise of data/analytics.json (shared
 *                             fetch, so the engine and the shell never double-load)
 *   DL_APP.rerender()         re-render the current tab
 *   DL_APP.myHero()           the hero id this profile marked as theirs, or null
 * Rule (template section 9): a 'data' receipt without a sample size is never
 * printed. The shell's own starter-build viewer follows it: every rate it shows
 * prints its match count beside it.
 */
'use strict';

/* ------------------------------------------------------------------ state */

const S = {
  meta: null,
  rules: null,
  patches: null,
  groups: {},        // key -> [entities]
  gmeta: [],         // ordered group descriptors (from meta.groups)
  gmap: {},          // key -> descriptor
  tabOf: {},         // group key -> tab name
  byId: {},          // "group:id" -> entity
  abByHero: {},      // hero id -> [abilities]
  index: [],         // search index rows
  view: 'start',
  q: '',
  hType: 'all',      // heroes tab: type filter
  hDiff: 'all',      // heroes tab: difficulty filter
  hSort: 'az',
  iSlot: 'all',      // items tab: weapon / vitality / spirit
  iTier: 'all',      // items tab: 1..4 or 'sb'
  iActive: false,    // items tab: only items with a button
  iSort: 'tier',
  bHero: null,       // builds fallback: chosen hero id
  booted: false
};

const $ = sel => document.querySelector(sel);
const app = () => $('#app');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[c]));
const reEsc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const VIEW_NAMES = ['start', 'heroes', 'items', 'builds', 'more'];

/* The Start walkthrough is an ORDERED SELECTION of existing mechanics, not new
   prose. Anything that does not resolve is dropped, so a pipeline rename
   shortens the list instead of rendering a dead step. */
const START_STEPS = [
  'mechanics:lanes-and-troopers',
  'mechanics:how-souls-work',
  'mechanics:denying',
  'mechanics:shop-tiers-and-investment',
  'mechanics:movement',
  'mechanics:guardians',
  'mechanics:walkers',
  'mechanics:death-and-respawn',
  'mechanics:mid-boss-and-rejuvenator',
  'mechanics:the-patron'
];

const SLOT_LABEL = { weapon: 'Weapon', vitality: 'Vitality', spirit: 'Spirit' };
const SLOT_ORDER = ['weapon', 'vitality', 'spirit'];

/* ------------------------------------------------------- persistence layer */

/* ONE namespaced key holding the whole blob. The name deliberately contains no
   "token", "auth" or "secret" and does not start with "sb-": import.astro's
   CREDENTIAL regex is tested BEFORE its allowlist and would silently drop this
   key from every backup and restore (R11 - do not relax the regex, rename the
   key). Multi-profile from day one; retrofitting profiles orphans saved data. */
const LS_KEY = 'deadlock_companion_v1'; // gitleaks:allow - localStorage namespace, not a secret

let ST = null;          // the whole blob
let saveTimer = null;

function blankProfile(name) {
  return { name: name || 'Me', manual: {}, imported: {}, pins: [], synced_at: null };
}
function blankState() {
  return { v: 1, active: 'p1', profiles: { p1: blankProfile('Me') } };
}

function loadState() {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return blankState();
    const o = JSON.parse(raw);
    if (!o || typeof o !== 'object' || !o.profiles || typeof o.profiles !== 'object') return blankState();
    for (const id of Object.keys(o.profiles)) {
      const p = o.profiles[id];
      if (!p || typeof p !== 'object') { delete o.profiles[id]; continue; }
      if (typeof p.name !== 'string') p.name = 'Profile';
      if (!p.manual || typeof p.manual !== 'object') p.manual = {};
      if (!p.imported || typeof p.imported !== 'object') p.imported = {};
      if (!Array.isArray(p.pins)) p.pins = [];
    }
    if (!Object.keys(o.profiles).length) return blankState();
    if (!o.profiles[o.active]) o.active = Object.keys(o.profiles)[0];
    o.v = 1;
    return o;
  } catch (e) {
    return blankState();
  }
}

function showSave(kind) {
  const el = $('#savePill');
  if (!el) return;
  el.hidden = false;
  el.className = 'save-pill' + (kind === 'saved' ? ' ok' : kind === 'failed' ? ' bad' : '');
  el.textContent = kind === 'saving' ? 'saving...' : kind === 'saved' ? 'saved' : 'save failed';
  if (kind === 'saved') {
    setTimeout(function () { const e2 = $('#savePill'); if (e2 && e2.textContent === 'saved') e2.hidden = true; }, 1400);
  }
}

/* 300 ms debounced write behind a visible pill. Never write synchronously per
   click - a fast tapper would hit localStorage on every keystroke. */
function saveState() {
  showSave('saving');
  if (saveTimer) clearTimeout(saveTimer);
  saveTimer = setTimeout(function () {
    saveTimer = null;
    try {
      localStorage.setItem(LS_KEY, JSON.stringify(ST));
      showSave('saved');
    } catch (e) {
      showSave('failed');
    }
  }, 300);
}

function prof() {
  if (!ST) ST = blankState();
  if (!ST.profiles[ST.active]) ST.active = Object.keys(ST.profiles)[0];
  return ST.profiles[ST.active];
}

/* Sparse manual-override layer over imported data. A read falls through
   manual -> imported; a write whose value EQUALS the imported value deletes the
   manual key, so the override layer only ever holds real divergence and a
   future import is not fought by stale ticks. (Nothing is imported today - the
   imported layer is the reserved slot for a future account sync.) */
function impGet(p, group, key) {
  const g = p.imported && p.imported[group];
  return g ? g[key] : undefined;
}
function ovGet(p, group, key, dflt) {
  const m = p.manual && p.manual[group];
  if (m && Object.prototype.hasOwnProperty.call(m, key)) return m[key];
  const iv = impGet(p, group, key);
  return iv === undefined ? dflt : iv;
}
function ovSet(group, key, val) {
  const p = prof();
  const iv = impGet(p, group, key);
  if (!p.manual) p.manual = {};
  if (val === iv || (iv === undefined && (val === false || val === null))) {
    if (p.manual[group]) {
      delete p.manual[group][key];
      if (!Object.keys(p.manual[group]).length) delete p.manual[group];
    }
  } else {
    if (!p.manual[group]) p.manual[group] = {};
    p.manual[group][key] = val;
  }
  saveState();
}

function myHero() {
  const v = ovGet(prof(), 'meta', 'myHero', null);
  return typeof v === 'string' && S.byId['heroes:' + v] ? v : null;
}
function setMyHero(id) { ovSet('meta', 'myHero', id); }
function stepDone(k) { return ovGet(prof(), 'steps', k, false) === true; }
function toggleStep(k) { ovSet('steps', k, !stepDone(k)); }
function isPinned(k) { return prof().pins.indexOf(k) !== -1; }
function togglePin(k) {
  const p = prof();
  const i = p.pins.indexOf(k);
  if (i >= 0) p.pins.splice(i, 1); else p.pins.push(k);
  saveState();
  return i < 0;
}

/* ------------------------------------------------------------- formatting */

function num(n) { return typeof n === 'number' ? n.toLocaleString('en-US') : String(n); }
function pct(n) { return typeof n === 'number' ? n + '%' : ''; }
function words(s) { return String(s == null ? '' : s).replace(/_/g, ' '); }
function cap(s) { s = String(s == null ? '' : s); return s.charAt(0).toUpperCase() + s.slice(1); }
function isNum(n) { return typeof n === 'number' && isFinite(n); }

/* Split on sentence ends WITHOUT a lookbehind - Safari only shipped lookbehind
   in 16.4 and a regex the parser rejects takes the whole file down. */
function firstSentences(text, n) {
  if (!text) return '';
  const s = String(text);
  const want = n || 1;
  let out = '', count = 0, i = 0;
  while (i < s.length) {
    out += s[i];
    if ('.!?'.indexOf(s[i]) !== -1 && (i + 1 >= s.length || /\s/.test(s[i + 1]))) {
      count++;
      if (count >= want) break;
    }
    i++;
  }
  return out.trim();
}

function prettyDate(iso) {
  if (!iso) return 'unknown';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso);
  const mo = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return d.getUTCDate() + ' ' + mo[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
}

function safeHex(c) { return /^#[0-9a-fA-F]{3,8}$/.test(String(c || '')) ? c : ''; }

/* --------------------------------------------------------------- entities */

function keyOf(g, id) { return g + ':' + id; }
function splitKey(k) { const i = k.indexOf(':'); return [k.slice(0, i), k.slice(i + 1)]; }
function ent(k) { return S.byId[k] || null; }
function nameOf(e) { return (e && (e.name || e.id)) || ''; }
function groupLabel(g) { const d = S.gmap[g]; return (d && d.label) || cap(g); }
function groupSingular(g) { const d = S.gmap[g]; return (d && d.singular) || cap(g); }
function tabOfGroup(g) { return S.tabOf[g] || 'more'; }
function hero(id) { return ent('heroes:' + id); }
function item(id) { return ent('items:' + id); }

function findByIdAnywhere(id) {
  const order = ['glossary', 'mechanics', 'items', 'heroes'];
  for (const g of order) if (S.byId[keyOf(g, id)]) return keyOf(g, id);
  return null;
}

function maxComplexity() {
  let m = 0;
  for (const h of (S.groups.heroes || [])) if (isNum(h.complexity) && h.complexity > m) m = h.complexity;
  return m || 4;
}
function minComplexity() {
  let m = Infinity;
  for (const h of (S.groups.heroes || [])) if (isNum(h.complexity) && h.complexity < m) m = h.complexity;
  return isFinite(m) ? m : 1;
}

function tierCost(t) {
  for (const it of (S.groups.items || [])) if (it.tier === t && !it.streetBrawl && isNum(it.cost)) return it.cost;
  return null;
}

function iconHtml(e, size, which) {
  const cls = 'spr s' + (size || 44);
  const src = e && (which === 'large' ? (e.iconLarge || e.icon) : e.icon);
  if (!src) return '<span class="spr-wrap miss"><span class="' + cls + '"></span></span>';
  return '<span class="spr-wrap"><img class="' + cls + '" src="' + esc(src) + '" alt="" loading="lazy" onerror="dlSprErr(this)" /></span>';
}
window.dlSprErr = function (img) {
  img.style.visibility = 'hidden';
  const w = img.closest('.spr-wrap');
  if (w) w.classList.add('miss');
};

function pipsHtml(c) {
  const mx = maxComplexity();
  let h = '<span class="pips" role="img" aria-label="Difficulty ' + esc(c) + ' of ' + esc(mx) + '">';
  for (let i = 1; i <= mx; i++) h += '<i' + (i <= c ? ' class="on"' : '') + '></i>';
  return h + '</span>';
}

function slotChip(slot) {
  return '<span class="chip t-' + esc(slot) + '">' + esc(SLOT_LABEL[slot] || cap(slot)) + '</span>';
}

function costChip(it) {
  if (it.streetBrawl) return '<span class="chip sb">Street Brawl only</span>';
  if (isNum(it.cost)) return '<span class="chip cost">' + esc(num(it.cost)) + ' souls</span>';
  return '';
}

/* ---------------------------------------------------- glossary auto-linking */

/* The beginner rule: any term that is not ordinary English is defined in the
   glossary and linked the FIRST time it appears. The linking is generated from
   the glossary group itself - nothing here names a game term. */
let GL_RE = null;
let GL_MAP = {};

function buildGlossaryLinker() {
  const list = (S.groups.glossary || []).filter(function (t) { return t && t.name; });
  GL_MAP = {};
  const names = list.map(function (t) { return t.name; }).sort(function (a, b) { return b.length - a.length; });
  for (const t of list) GL_MAP[t.name.toLowerCase()] = keyOf('glossary', t.id);
  GL_RE = names.length ? new RegExp('\\b(' + names.map(reEsc).join('|') + ')(es|s)?\\b', 'gi') : null;
}

/* Escapes FIRST, then links, so the replacement can only ever add our own
   button markup. `seen` is shared across a whole sheet so a term links once. */
function proseHtml(text, seen, selfKey) {
  const t = esc(text);
  if (!GL_RE || !seen) return t;
  return t.replace(GL_RE, function (m, name) {
    const k = GL_MAP[String(name).toLowerCase()];
    if (!k || k === selfKey || seen[k]) return m;
    seen[k] = true;
    return '<button class="gl" data-ent="' + esc(k) + '">' + m + '</button>';
  });
}

/* THE THREE FIXED SECTIONS. Same headings, same order, on every entity. */
function beginnerHtml(e, seen, selfKey) {
  const b = e.beginner;
  if (!b || (!b.whatItIs && !b.whyItMatters && !b.whenToUseIt)) {
    return '<div class="beg-missing">Plain-language notes for this entry have not been written yet. ' +
      'The numbers below come straight from the game data; the "What it is / Why it matters / When to use it" ' +
      'lines are still owed for this entry.</div>';
  }
  let h = '<div class="beg">';
  const rows = [['What it is', b.whatItIs], ['Why it matters', b.whyItMatters], ['When to use it', b.whenToUseIt]];
  for (const r of rows) {
    if (!r[1]) continue;
    h += '<p class="bh">' + esc(r[0]) + '</p><p class="bp">' + proseHtml(r[1], seen, selfKey) + '</p>';
  }
  return h + '</div>';
}

function linkChip(k, label) {
  if (!k) return '<span class="chip">' + esc(label) + '</span>';
  return '<button class="lchip" data-ent="' + esc(k) + '">' + esc(label) + '</button>';
}

/* rows: [label, value, valueIsHtml]. `stacked` puts the label above the value, for
   facts whose label is a sentence (the mechanics facts table). */
function statTable(rows, stacked) {
  let h = '';
  for (const r of rows) {
    if (r[1] == null || r[1] === '') continue;
    h += '<div class="st' + (stacked ? ' stack' : '') + '"><span class="k">' + esc(r[0]) + '</span><span class="v">' + (r[2] ? r[1] : esc(r[1])) + '</span></div>';
  }
  return h ? '<div class="stats">' + h + '</div>' : '';
}

/* A numeric stat from an ability or item effect. Only the Spirit Power scaling
   is surfaced (the other scale keys are engine internals); the ratio itself is
   not printed because the data does not say what it is a ratio OF. */
function statValueHtml(s) {
  let h = esc(s.text != null ? s.text : '');
  if (s.scale && s.scale.stat === 'spirit') h += ' <span class="faint">(grows with Spirit Power)</span>';
  else if (s.scale && s.scale.stat === 'levelupboons') h += ' <span class="faint">(grows as you level up)</span>';
  return h;
}

function dataWindowNote() {
  const m = S.meta || {};
  const w = (m.analytics && m.analytics.window) || {};
  const p = m.patch || w.patch || {};
  if (!isNum(w.days)) return '';
  return 'Match numbers cover ' + w.days + ' days of games played after patch ' + (p.title || 'the latest patch') +
    '. They show what players did and how those games went, not proof that something is best.';
}

/* ------------------------------------------------------------ detail sheet */

let sheetOpen = false;

function sheetShell(inner, hdr) {
  return '<button class="sheet-close" data-close>Close</button><div class="sheet-grab"></div>' +
    '<div class="sheet-hero">' + hdr.icon + '<div style="min-width:0"><h3>' + esc(hdr.title) + '</h3>' +
    '<div class="ssub">' + hdr.sub + '</div>' +
    (hdr.chips ? '<div class="row wrap g6">' + hdr.chips + '</div>' : '') + '</div></div>' + inner;
}

function pinButtons(k, g) {
  let h = '<div class="actrow">';
  h += '<button class="tbtn' + (isPinned(k) ? ' on' : '') + '" data-pin="' + esc(k) + '">' + (isPinned(k) ? 'Saved' : 'Save') + '</button>';
  if (g === 'heroes') {
    const id = splitKey(k)[1];
    h += '<button class="tbtn' + (myHero() === id ? ' on' : '') + '" data-myhero="' + esc(id) + '">' +
      (myHero() === id ? 'My hero' : 'Make this my hero') + '</button>';
  }
  return h + '</div>';
}

/* ---- hero sheet ---- */

function starterPicks(h) {
  const out = [];
  for (const t of (h.topItems || [])) {
    const it = item(t.item);
    if (it && !it.streetBrawl && isNum(it.tier) && it.tier <= 2) out.push({ t: t, it: it });
    if (out.length >= 4) break;
  }
  return out;
}

function itemBuyRow(t, it, h) {
  const base = h && h.perf && isNum(h.perf.winRate) ? h.perf.winRate : null;
  let rm = 'Bought in ' + pct(t.buyShare) + ' of ' + nameOf(h) + ' matches. Those games were won ' + pct(t.winRate) +
    ' of the time (' + num(t.matches) + ' matches)';
  if (base != null && isNum(t.lift)) rm += '; ' + nameOf(h) + ' wins ' + pct(base) + ' overall';
  rm += '.';
  return '<button class="rowcard slot-' + esc(it.slot) + '" data-ent="' + esc(keyOf('items', it.id)) + '">' +
    iconHtml(it, 44) + '<span class="rb"><span class="rn">' + esc(it.name) + '</span><span class="rm full">' + esc(rm) + '</span></span>' +
    '<span class="rc">' + costChip(it) + '</span></button>';
}

function abilityHtml(a, h, focus) {
  const bph = h.beginner && h.beginner.abilities && h.beginner.abilities[a.id];
  const sameAsName = a.quip && String(a.quip).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() === String(a.name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const short = bph || (a.quip && !sameAsName ? a.quip : '') || firstSentences(a.text, 1) || '';
  const tag = a.kind === 'ultimate' ? 'Ultimate' : 'Ability ' + a.slot;
  let more = '';
  if (a.text) more += '<h5>In the game\'s own words</h5><p>' + esc(a.text) + '</p>';
  const stats = (a.stats || []).filter(function (s) { return s && s.label && s.text != null && s.text !== ''; });
  if (stats.length) {
    more += '<h5>Numbers</h5>' + statTable(stats.map(function (s) { return [s.label, statValueHtml(s), true]; }));
  }
  const tiers = (a.tiers || []).filter(function (t) { return t && (t.text || (t.changes && t.changes.length)); });
  if (tiers.length) {
    more += '<h5>Upgrades (spend ability points)</h5><ul class="up">' + tiers.map(function (t) {
      const ch = (t.changes || []).filter(function (c) { return c && c.label && c.text; })
        .map(function (c) { return esc(c.label) + ': ' + esc(c.text); }).join('; ');
      return '<li><b>Upgrade ' + esc(t.tier) + '</b> ' + (ch || '') + (t.text ? (ch ? '<br />' : '') + esc(t.text) : '') + '</li>';
    }).join('') + '</ul>';
  }
  const isFocus = focus === a.id;
  return '<details class="abil' + (isFocus ? ' hl' : '') + '" data-ab="' + esc(a.id) + '"' + (isFocus ? ' open' : '') + '>' +
    '<summary>' + iconHtml(a, 44) + '<span class="ab-b"><span class="ab-n">' + esc(a.name) +
    '<span class="chip">' + esc(tag) + '</span></span>' +
    (short ? '<span class="ab-q" style="display:block">' + esc(short) + '</span>' : '') +
    (a.statsLine ? '<span class="ab-q faint" style="display:block">' + esc(a.statsLine) + '</span>' : '') +
    '</span><span class="ab-chev">details</span></summary>' +
    (more ? '<div class="ab-more">' + more + '</div>' : '') + '</details>';
}

function heroSheetBody(e, focus) {
  const k = keyOf('heroes', e.id);
  const seen = {};
  const b = e.beginner || {};
  let h = beginnerHtml(e, seen, k);

  if (b.firstHeroReason) {
    h += '<div class="note"><b>A good first hero?</b> ' + proseHtml(b.firstHeroReason, seen, k) + '</div>';
  }

  // At a glance - same facts and labels as the vault page (wiki-spec.json).
  const w = e.weapon || {};
  const st = e.stats || {};
  const pf = e.perf || {};
  const rows = [];
  rows.push(['Type', e.typeLabel || cap(e.type)]);
  if (isNum(e.complexity)) rows.push(['Difficulty', e.complexity + ' of ' + maxComplexity()]);
  if (e.playstyle) rows.push(['Playstyle (game text)', e.playstyle]);
  if (w.name) rows.push(['Weapon', w.name + (w.tag ? ' (' + w.tag + ')' : '')]);
  if (isNum(w.damagePerShot) && isNum(w.shotsPerSecond) && isNum(w.clipSize)) {
    rows.push(['Weapon damage', w.damagePerShot + ' per shot, ' + w.shotsPerSecond + ' shots per second, clip of ' + w.clipSize]);
  }
  if (isNum(w.dps)) {
    /* weapon.dpsDisputed: the game-data API and the wiki weapon card disagree (meta.sourceClaims
       weapon-dps-derivation). Never print the number as plain fact; hedge it on the sheet itself. */
    if (w.dpsDisputed === true) rows.push(['Damage per second', esc(String(w.dps)) + ' <span class="faint">(unconfirmed: the sources disagree on this weapon, see the More tab)</span>', true]);
    else rows.push(['Damage per second', String(w.dps)]);
  }
  if (isNum(st.max_health)) rows.push(['Health', num(st.max_health)]);
  if (isNum(st.base_health_regen)) rows.push(['Health regeneration', st.base_health_regen + ' per second']);
  if (isNum(st.max_move_speed)) rows.push(['Move speed', st.max_move_speed + ' m/s']);
  if (isNum(st.stamina)) rows.push(['Stamina bars', String(st.stamina)]);
  if (isNum(pf.winRate) && isNum(pf.matches)) {
    rows.push(['Win rate', pct(pf.winRate) + ' over ' + num(pf.matches) + ' matches (' + pf.windowDays + '-day window)']);
  }
  if (isNum(pf.pickShare)) rows.push(['Pick share', pct(pf.pickShare)]);
  if (isNum(pf.banRate)) rows.push(['Ban rate', pct(pf.banRate)]);
  const mf = e.maxFirst && ent(keyOf('abilities', e.maxFirst.ability));
  if (mf && isNum(e.maxFirst.winRate) && isNum(e.maxFirst.matches)) {
    rows.push(['Ability most often maxed first', mf.name + ' (' + pct(e.maxFirst.winRate) + ' win rate, ' + num(e.maxFirst.matches) + ' matches)']);
  }
  const glance = '<div class="sec-h">At a glance</div>' + statTable(rows);

  // Abilities with local icons, beginner phrasing where written.
  const abs = S.abByHero[e.id] || [];
  if (abs.length) {
    h += '<div class="sec-h">Abilities</div>';
    for (const a of abs) h += abilityHtml(a, e, focus);
  }

  // Starter build, derived from what this hero's players actually bought.
  const picks = starterPicks(e);
  const t1 = tierCost(1), t2 = tierCost(2);
  if (picks.length) {
    h += '<div class="sec-h">Starter build</div>';
    h += '<p class="lede" style="margin:0 0 8px">The cheap items' + (t1 && t2 ? ' (' + num(t1) + ' and ' + num(t2) + ' souls)' : '') +
      ' that ' + esc(e.name) + ' players bought most often, with the number of matches behind each figure.</p>';
    if (b.starterBuildWhy) h += '<p class="bp" style="margin:0 0 8px">' + proseHtml(b.starterBuildWhy, seen, k) + '</p>';
    for (const p of picks) h += itemBuyRow(p.t, p.it, e);
  }
  const rest = (e.topItems || []).filter(function (t) {
    return !picks.some(function (p) { return p.t.item === t.item; }) && item(t.item);
  });
  if (rest.length) {
    h += '<div class="sec-h">Also bought a lot</div>';
    for (const t of rest) h += itemBuyRow(t, item(t.item), e);
  }

  // Matchups.
  const mu = e.matchups || {};
  const muRow = function (m) {
    const o = hero(m.hero);
    if (!o) return '';
    return '<button class="rowcard" data-ent="' + esc(keyOf('heroes', o.id)) + '">' + iconHtml(o, 36) +
      '<span class="rb"><span class="rn">' + esc(o.name) + '</span><span class="rm full">' + esc(e.name + ' wins ' + pct(m.winRate) + ' of ' + num(m.matches) + ' matches against ' + o.name + '.') + '</span></span></button>';
  };
  if ((mu.strongAgainst || []).length) {
    h += '<div class="sec-h">Does best against</div>' + mu.strongAgainst.map(muRow).join('');
  }
  if ((mu.weakAgainst || []).length) {
    h += '<div class="sec-h">Struggles against</div>' + mu.weakAgainst.map(muRow).join('');
  }
  const note = dataWindowNote();
  if (note) h += '<div class="note">' + esc(note) + '</div>';
  h += glance;
  h += pinButtons(k, 'heroes');
  return h;
}

/* ---- item sheet ---- */

function effectHtml(eff) {
  const labels = { innate: 'Always gives', passive: 'Passive effect', active: 'Active (you press it)' };
  const stats = (eff.stats || []).filter(function (s) { return s && s.label && s.text != null && s.text !== ''; });
  if (!eff.text && !stats.length) return '';
  let h = '<div class="eff"><div class="ek">' + esc(labels[eff.kind] || cap(words(eff.kind))) + '</div>';
  if (eff.text) h += '<p>' + esc(eff.text) + '</p>';
  h += statTable(stats.map(function (s) { return [s.label, statValueHtml(s), true]; }));
  return h + '</div>';
}

function itemSheetBody(e) {
  const k = keyOf('items', e.id);
  const seen = {};
  let h = beginnerHtml(e, seen, k);
  const pf = e.perf || {};
  const rows = [];
  rows.push(['Type', SLOT_LABEL[e.slot] || cap(e.slot)]);
  if (e.streetBrawl) rows.push(['Street Brawl only', 'Yes']);
  else {
    if (isNum(e.tier)) rows.push(['Tier', String(e.tier)]);
    if (isNum(e.cost)) rows.push(['Cost', num(e.cost) + ' souls']);
  }
  if (e.activation) rows.push(['Use', cap(words(e.activation))]);
  if (e.isActive) rows.push(['Active item', 'Yes']);
  if (isNum(pf.winRate) && isNum(pf.matches)) {
    rows.push(['Win rate when bought', pct(pf.winRate) + ' over ' + num(pf.matches) + ' matches (' + pf.windowDays + '-day window)']);
  }
  if (isNum(pf.avgBuyMinute)) rows.push(['Usually bought around', 'minute ' + pf.avgBuyMinute]);
  h += '<div class="sec-h">At a glance</div>' + statTable(rows);
  if (e.textMissingAtSource) {
    h += '<div class="note">The game data has no description text for this item, only its numbers.</div>';
  }
  const effs = (e.effects || []).map(effectHtml).join('');
  if (effs) h += '<div class="sec-h">Stats and effects</div>' + effs;

  const linkList = function (ids) {
    return '<div class="linkrow">' + ids.map(function (id) {
      const o = item(id);
      return o ? linkChip(keyOf('items', o.id), o.name) : '';
    }).join('') + '</div>';
  };
  if ((e.components || []).length) h += '<div class="sec-h">Built from</div>' + linkList(e.components);
  if ((e.builtInto || []).length) h += '<div class="sec-h">Builds into</div>' + linkList(e.builtInto);
  const pw = e.beginner && e.beginner.pairsWith;
  if (Array.isArray(pw) && pw.length) h += '<div class="sec-h">Pairs well with</div>' + linkList(pw);

  if ((e.topBuyers || []).length) {
    h += '<div class="sec-h">Heroes who buy it most</div>';
    for (const t of e.topBuyers) {
      const o = hero(t.hero);
      if (!o) continue;
      h += '<button class="rowcard" data-ent="' + esc(keyOf('heroes', o.id)) + '">' + iconHtml(o, 36) +
        '<span class="rb"><span class="rn">' + esc(o.name) + '</span><span class="rm full">' +
        esc('Bought in ' + pct(t.buyShare) + ' of their matches. Those games were won ' + pct(t.winRate) + ' of the time (' + num(t.matches) + ' matches).') +
        '</span></span></button>';
    }
  }
  if (e.perf) {
    const note = dataWindowNote();
    if (note) h += '<div class="note">' + esc(note) + '</div>';
  }
  h += pinButtons(k, 'items');
  return h;
}

/* ---- mechanic + glossary sheet ---- */

/* Source disagreements the pipeline recorded (meta.sourceClaims). The slot-count
   conflict is attached to the mechanic that discusses slots; every unresolved
   claim is ALSO listed on More, so none can go unshown. */
function unresolvedClaims() {
  const sc = (S.meta && S.meta.sourceClaims) || [];
  return sc.filter(function (c) { return c && /^UNRESOLVED/i.test(String(c.status || '')); });
}
function claimsForMechanic(m) {
  return unresolvedClaims().filter(function (c) {
    return /slot/i.test(c.id || '') && /slot/i.test(m.id || '');
  });
}
/* A claim is shown to players ONLY through its public wording (c.public: a topic
   title plus one plain line per source, written in tools/config.json and copied
   by build_data). The internal claim / counterClaim / status text carries field
   names and planning-note wording and is never rendered (validate.mjs PUBLIC-TEXT). */
function claimHtml(c) {
  const p = c && c.public;
  if (!p || !p.title || !Array.isArray(p.lines) || !p.lines.length) return '';
  return '<div class="note warn"><b>' + esc(p.title) + '</b><br />' +
    p.lines.map(function (l) { return esc(l); }).join('<br />') +
    '<br /><span class="faint">The sources disagree, so treat both figures as unconfirmed until someone can check it in the game itself.</span></div>';
}

function genericSheetBody(e, g) {
  const k = keyOf(g, e.id);
  const seen = {};
  let h = beginnerHtml(e, seen, k);
  if (g === 'mechanics') for (const c of claimsForMechanic(e)) h += claimHtml(c);
  const facts = (e.facts || []).filter(function (f) { return f && f.label && f.value != null && f.value !== ''; });
  if (facts.length) {
    h += '<div class="sec-h">Facts from the game and its wiki</div>' + statTable(facts.map(function (f) { return [f.label, f.value]; }), true);
  }
  const rel = (e.related || []).map(function (id) {
    const rk = findByIdAnywhere(id);
    return rk ? linkChip(rk, nameOf(ent(rk))) : '';
  }).join('');
  if (rel) h += '<div class="sec-h">See also</div><div class="linkrow">' + rel + '</div>';
  h += pinButtons(k, g);
  return h;
}

function openEntity(k) {
  let [g, id] = splitKey(k);
  let e = ent(k);
  if (!e) return;
  const origKey = k;
  let focus = null;
  if (g === 'abilities') {          // abilities live inside their hero's sheet
    focus = id;
    g = 'heroes'; id = e.hero; k = keyOf(g, id); e = ent(k);
    if (!e) return;
  }
  const body = $('#sheetBody');
  const sh = $('#sheet');
  if (!body || !sh) return;

  let inner, hdr;
  if (g === 'heroes') {
    inner = heroSheetBody(e, focus);
    hdr = {
      icon: iconHtml(e, 88),
      title: e.name,
      sub: esc(groupSingular(g)) + ' &middot; ' + esc(e.typeLabel || cap(e.type)),
      chips: isNum(e.complexity) ? '<span class="chip">Difficulty ' + esc(e.complexity) + ' of ' + esc(maxComplexity()) + ' ' + pipsHtml(e.complexity) + '</span>' : ''
    };
  } else if (g === 'items') {
    inner = itemSheetBody(e);
    hdr = {
      icon: iconHtml(e, 88),
      title: e.name,
      sub: esc(groupSingular(g)) + ' &middot; ' + esc(SLOT_LABEL[e.slot] || cap(e.slot)) + (e.streetBrawl ? '' : ' &middot; Tier ' + esc(e.tier)),
      chips: slotChip(e.slot) + costChip(e) + (e.isActive ? '<span class="chip">Has a button</span>' : '')
    };
  } else {
    inner = genericSheetBody(e, g);
    hdr = {
      icon: '',
      title: e.name,
      sub: esc(groupSingular(g)) + (e.category ? ' &middot; ' + esc(e.category) : ''),
      chips: ''
    };
  }
  body.innerHTML = sheetShell(inner, hdr);
  body.scrollTop = 0;
  sh.hidden = false;
  sheetOpen = true;
  try { document.body.style.overflow = 'hidden'; } catch (err) { /* no-op */ }
  setHash('#/e/' + splitKey(origKey)[0] + '/' + splitKey(origKey)[1]);
  if (focus) {
    const d = body.querySelector('details[data-ab="' + focus.replace(/"/g, '') + '"]');
    if (d) { try { d.scrollIntoView({ block: 'center' }); } catch (err) { /* no-op */ } }
  }
}

function closeSheet() {
  const sh = $('#sheet');
  if (sh) sh.hidden = true;
  sheetOpen = false;
  try { document.body.style.overflow = ''; } catch (err) { /* no-op */ }
  setHash('#/' + S.view);
}

/* ------------------------------------------------------------------ search */

function norm(s) { return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }

function buildIndex() {
  S.index = [];
  for (const d of S.gmeta) {
    for (const e of (S.groups[d.key] || [])) {
      let extra = '';
      if (d.key === 'heroes') extra = [e.typeLabel, e.role, (e.tags || []).join(' '), e.weapon && e.weapon.name].join(' ');
      else if (d.key === 'items') extra = [e.slot, 'tier ' + e.tier, words((e.shopFilters || []).join(' ')), e.streetBrawl ? 'street brawl' : '', firstSentences(e.text, 1)].join(' ');
      else if (d.key === 'abilities') { const hh = hero(e.hero); extra = [hh && hh.name, e.quip].join(' '); }
      else extra = [e.category].join(' ');
      let sub = groupSingular(d.key);
      if (d.key === 'abilities') { const hh = hero(e.hero); if (hh) sub = 'Ability - ' + hh.name; }
      else if (d.key === 'items') sub = 'Item - ' + (e.streetBrawl ? 'Street Brawl' : (SLOT_LABEL[e.slot] || cap(e.slot)));
      else if (d.key === 'heroes') sub = 'Hero - ' + (e.typeLabel || cap(e.type));
      S.index.push({ k: keyOf(d.key, e.id), g: d.key, n: nameOf(e), nn: norm(nameOf(e)), hay: norm(nameOf(e) + ' ' + extra), sub: sub });
    }
  }
}

function searchRows(q, excludeGroups) {
  const qn = norm(q);
  if (!qn) return [];
  const toks = qn.split(' ');
  const out = [];
  for (const r of S.index) {
    if (excludeGroups && excludeGroups.indexOf(r.g) !== -1) continue;
    let ok = true;
    for (const t of toks) if (r.hay.indexOf(t) === -1) { ok = false; break; }
    if (!ok) continue;
    const at = r.nn.indexOf(qn);
    out.push({ r: r, rank: at === 0 ? 0 : at > 0 ? 1 : 2 });
  }
  out.sort(function (a, b) { return a.rank - b.rank || a.r.n.localeCompare(b.r.n); });
  return out.slice(0, 30).map(function (x) { return x.r; });
}

function searchHtml(placeholder) {
  return '<div class="search-wrap">' +
    '<span class="search-ic">&#128269;</span>' +
    '<input id="q" class="search" type="search" autocomplete="off" autocorrect="off" enterkeyhint="search" ' +
    'spellcheck="false" placeholder="' + esc(placeholder) + '" value="' + esc(S.q) + '" />' +
    (S.q ? '<button class="search-clear" data-clearq aria-label="Clear search">&#10005;</button>' : '') +
    '<div id="suggest"></div></div>';
}

/* Groups the CURRENT tab already filters inline; the dropdown carries every
   other entity, so the field reaches all of them from all five tabs. */
function inlineGroups() {
  if (S.view === 'heroes') return ['heroes'];
  if (S.view === 'items') return ['items'];
  return [];
}

function renderSuggest() {
  const box = $('#suggest');
  if (!box) return;
  if (!S.q.trim()) { box.innerHTML = ''; box.className = ''; return; }
  const ex = inlineGroups();
  const rows = searchRows(S.q, ex);
  if (!rows.length) {
    if (ex.length) { box.innerHTML = ''; box.className = ''; return; }
    box.className = 'suggest';
    box.innerHTML = '<div class="sug-empty">Nothing matches "' + esc(S.q) + '".</div>';
    return;
  }
  box.className = 'suggest';
  box.innerHTML = rows.map(function (r) {
    return '<button class="sug-row" data-ent="' + esc(r.k) + '">' +
      '<span class="nm">' + esc(r.n) + '</span><span class="tg">' + esc(r.sub) + '</span></button>';
  }).join('');
}

/* ----------------------------------------------------------- shared blocks */

function patchInfo() {
  const m = S.meta || {};
  const w = (m.analytics && m.analytics.window) || {};
  return m.patch || w.patch || null;
}

/* The freshness stamp. Rendered by the SHELL on Start, Builds and More, so a
   tool lane cannot ship a tab without it. Every figure is read from meta.json. */
function stampHtml(id, withMatchData, compact) {
  const m = S.meta || {};
  const p = patchInfo();
  const w = (m.analytics && m.analytics.window) || {};
  let h = '<div class="card"' + (id ? ' id="' + esc(id) + '"' : '') + '><div class="fresh">' +
    '<span>Data pulled <b>' + esc(prettyDate(m.pulledAt)) + '</b></span>';
  if (p && p.title) {
    h += '<span>Reflects patch <b>' +
      (p.link ? '<a href="' + esc(p.link) + '" target="_blank" rel="noopener noreferrer">' + esc(p.title) + '</a>' : esc(p.title)) +
      '</b>' + (p.date ? ' (posted ' + esc(prettyDate(p.date)) + ')' : '') + '</span>';
  }
  if (m.client && isNum(m.client.clientVersion)) {
    h += '<span>Game build <b>' + esc(m.client.clientVersion) + '</b></span>';
  }
  h += '</div>';
  if (withMatchData && m.analytics && isNum(w.days) && isNum(m.analytics.totalHeroMatches)) {
    h += '<p class="small muted" style="margin:8px 0 0">Match numbers: <b>' + esc(num(m.analytics.totalHeroMatches)) +
      '</b> hero-matches over <b>' + esc(w.days) + '</b> days. ' + esc(cap(m.analytics.filters || '')) + '.' +
      (m.analytics.sampleNote ? ' ' + esc(m.analytics.sampleNote) : '') + '</p>';
  }
  if (!compact) {
    const fr = m.sources && m.sources['valve-forum'];
    h += '<p class="small muted" style="margin:8px 0 0">' +
      (fr ? 'If the <a href="' + esc(fr.url) + '" target="_blank" rel="noopener noreferrer">Valve changelog</a> shows a newer post than the patch named here, treat the numbers as old. ' : 'If a newer patch has been posted than the one named here, treat the numbers as old. ') +
      'The data is re-pulled when a new patch lands.</p>';
  }
  return h + '</div>';
}

function renderPreBanner() {
  const el = $('#prebar');
  if (!el) return;
  const m = S.meta || {};
  const v = m.verification || {};
  const a = m.access || {};
  let txt = '';
  if (v.note) txt = v.note;
  else if (a.limitedAccess) txt = 'Deadlock is an invite-only playtest.';
  if (!txt) { el.innerHTML = ''; return; }
  el.innerHTML = '<div class="pb"><span class="pbi">&#9888;</span><span>' + esc(txt) + '</span></div>';
}

function distinct(list, field) {
  const seen = [];
  for (const e of list) {
    const v = e[field];
    if (v != null && v !== '' && seen.indexOf(v) === -1) seen.push(v);
  }
  return seen;
}

function heroRow(h, line) {
  return '<button class="rowcard" data-ent="' + esc(keyOf('heroes', h.id)) + '">' + iconHtml(h, 44) +
    '<span class="rb"><span class="rn">' + esc(h.name) + '</span><span class="rm">' + esc(line || '') + '</span></span>' +
    '<span class="rc"><span class="chip hero">' + esc(h.typeLabel || cap(h.type)) + '</span>' + (isNum(h.complexity) ? pipsHtml(h.complexity) : '') + '</span></button>';
}

function itemRow(it, line) {
  return '<button class="rowcard slot-' + esc(it.slot) + '" data-ent="' + esc(keyOf('items', it.id)) + '">' + iconHtml(it, 44) +
    '<span class="rb"><span class="rn">' + esc(it.name) + '</span><span class="rm">' +
    esc(line != null ? line : firstSentences((it.beginner || {}).whatItIs, 2) || it.text || '') + '</span></span>' +
    '<span class="rc">' + costChip(it) + '<span class="chip t-' + esc(it.slot) + '">' + esc(SLOT_LABEL[it.slot] || cap(it.slot)) + '</span></span></button>';
}

/* -------------------------------------------------------------- views: Start */

function easiestHeroes() {
  const hs = S.groups.heroes || [];
  const min = minComplexity();
  const list = hs.filter(function (h) { return h.complexity === min; });
  const hasR = function (h) { return h.beginner && h.beginner.firstHeroReason ? 1 : 0; };
  list.sort(function (a, b) {
    return hasR(b) - hasR(a) ||
      (((b.perf && b.perf.pickShare) || 0) - ((a.perf && a.perf.pickShare) || 0)) ||
      a.name.localeCompare(b.name);
  });
  return { list: list, min: min };
}

function renderStart() {
  let h = '<div class="view">';
  if (S.notFound) h += '<div class="note warn" role="status" data-notfound>That page does not exist.</div>';
  h += searchHtml('Search heroes, items, words, anything');
  h += stampHtml('startStamp', false, true);

  // 1. First 10 minutes.
  const steps = START_STEPS.filter(function (k) { return ent(k); });
  const doneN = steps.filter(stepDone).length;
  h += '<h2 class="vh">Your first 10 minutes</h2>';
  h += '<p class="lede">Read these in order and you know how a match runs. Tap a step for the full explanation, and tick it when it makes sense.</p>';
  if (steps.length) {
    h += '<div class="prog" role="img" aria-label="' + doneN + ' of ' + steps.length + ' steps done"><i style="width:' + Math.round(100 * doneN / steps.length) + '%"></i></div>';
    h += '<ol class="steps">';
    for (const k of steps) {
      const e = ent(k);
      const line = firstSentences((e.beginner || {}).whatItIs, 2);
      h += '<li' + (stepDone(k) ? ' class="done"' : '') + '><button class="sl" data-ent="' + esc(k) + '">' + esc(e.name) + '</button>' +
        '<div class="sd">' + esc(line) + '</div>' +
        '<div class="sa"><button class="tbtn" data-ent="' + esc(k) + '">Read more</button>' +
        '<button class="tbtn' + (stepDone(k) ? ' on' : '') + '" data-step="' + esc(k) + '">' + (stepDone(k) ? 'Got it' : 'Mark as got it') + '</button></div></li>';
    }
    h += '</ol>';
  } else {
    h += '<div class="card">The walkthrough steps are not in this dataset. Use the mechanics list on the More tab.</div>';
  }
  h += '<div class="row g8"><button class="tbtn" data-goto="more">More about how the game works</button></div>';

  // 2. Pick your first hero.
  const eh = easiestHeroes();
  if (eh.list.length) {
    h += '<h2 class="vh" style="margin-top:22px">Pick your first hero</h2>';
    h += '<p class="lede">Heroes with difficulty ' + eh.min + ' of ' + maxComplexity() + ', the lowest rating in the game data. ' +
      'Heroes with a written reason come first, then the most played.</p>';
    for (const hh of eh.list.slice(0, 6)) {
      const b = hh.beginner || {};
      const line = b.firstHeroReason || firstSentences(b.whatItIs, 1) || hh.role || '';
      h += heroRow(hh, line);
    }
    if (eh.list.length > 6) {
      h += '<div class="row g8"><button class="tbtn" data-easy>See all ' + eh.list.length + ' heroes at difficulty ' + eh.min + '</button></div>';
    }
  }

  // 3. Saved.
  const pinKeys = prof().pins.filter(function (pk) { return ent(pk); });
  if (pinKeys.length) {
    h += '<h2 class="vh" style="margin-top:22px">Saved by you</h2>';
    for (const pk of pinKeys) {
      const pe = ent(pk);
      const g = splitKey(pk)[0];
      if (g === 'heroes') h += heroRow(pe, firstSentences((pe.beginner || {}).whatItIs, 1));
      else if (g === 'items') h += itemRow(pe);
      else h += '<button class="rowcard" data-ent="' + esc(pk) + '"><span class="rb"><span class="rn">' + esc(pe.name) +
        '</span><span class="rm">' + esc(firstSentences((pe.beginner || {}).whatItIs, 1)) + '</span></span></button>';
    }
  }

  // 4. Glossary.
  const gl = S.groups.glossary || [];
  if (gl.length) {
    h += '<h2 class="vh" style="margin-top:22px">Words you will hear</h2>';
    h += '<p class="lede">' + gl.length + ' terms in plain English. Any of them also shows up in the search above.</p>';
    const cats = distinct(gl, 'category');
    for (const c of cats) {
      h += '<h3 class="sh">' + esc(c) + '</h3>';
      for (const t of gl.filter(function (x) { return x.category === c; })) {
        h += '<button class="rowcard" data-ent="' + esc(keyOf('glossary', t.id)) + '"><span class="rb"><span class="rn">' + esc(t.name) +
          '</span><span class="rm">' + esc(firstSentences((t.beginner || {}).whatItIs, 1)) + '</span></span></button>';
      }
    }
  }
  h += '</div>';
  return h;
}

/* ------------------------------------------------------------- views: Heroes */

function renderHeroes() {
  const hs = S.groups.heroes || [];
  const types = [];
  for (const x of hs) {
    if (!types.some(function (t) { return t.key === x.type; })) types.push({ key: x.type, label: x.typeLabel || cap(x.type) });
  }
  types.sort(function (a, b) { return a.label.localeCompare(b.label); });
  const diffs = distinct(hs, 'complexity').filter(isNum).sort(function (a, b) { return a - b; });
  const dmin = diffs[0], dmax = diffs[diffs.length - 1];

  let h = '<div class="view">';
  h += searchHtml('Search heroes and everything else');
  h += '<div class="chiprow">' +
    '<button class="fbtn' + (S.hType === 'all' ? ' on' : '') + '" data-htype="all">All ' + hs.length + '</button>' +
    types.map(function (t) {
      const n = hs.filter(function (x) { return x.type === t.key; }).length;
      return '<button class="fbtn' + (S.hType === t.key ? ' on' : '') + '" data-htype="' + esc(t.key) + '">' + esc(t.label) + ' ' + n + '</button>';
    }).join('') + '</div>';
  h += '<div class="chiprow">' +
    '<button class="fbtn' + (S.hDiff === 'all' ? ' on' : '') + '" data-hdiff="all">Any difficulty</button>' +
    diffs.map(function (d) {
      return '<button class="fbtn' + (String(S.hDiff) === String(d) ? ' on' : '') + '" data-hdiff="' + esc(d) + '">Difficulty ' + esc(d) +
        (d === dmin ? ' (easiest)' : d === dmax ? ' (hardest)' : '') + '</button>';
    }).join('') + '</div>';
  h += '<div class="ctl"><label for="hsort">Sort</label><select id="hsort" class="sel">' +
    [['az', 'A to Z'], ['played', 'Most played'], ['easy', 'Easiest first']].map(function (o) {
      return '<option value="' + o[0] + '"' + (S.hSort === o[0] ? ' selected' : '') + '>' + o[1] + '</option>';
    }).join('') + '</select></div>';
  h += '<div id="listRegion"></div></div>';
  return h;
}

function heroList() {
  const qn = norm(S.q);
  const toks = qn ? qn.split(' ') : [];
  const list = (S.groups.heroes || []).filter(function (x) {
    if (S.hType !== 'all' && x.type !== S.hType) return false;
    if (S.hDiff !== 'all' && String(x.complexity) !== String(S.hDiff)) return false;
    if (!toks.length) return true;
    const hay = norm([x.name, x.typeLabel, x.role, (x.tags || []).join(' '), x.weapon && x.weapon.name].join(' '));
    for (const t of toks) if (hay.indexOf(t) === -1) return false;
    return true;
  });
  list.sort(function (a, b) {
    if (S.hSort === 'played') return (((b.perf && b.perf.pickShare) || 0) - ((a.perf && a.perf.pickShare) || 0)) || a.name.localeCompare(b.name);
    if (S.hSort === 'easy') return ((a.complexity || 0) - (b.complexity || 0)) || a.name.localeCompare(b.name);
    return a.name.localeCompare(b.name);
  });
  return list;
}

function fillHeroes() {
  const box = $('#listRegion');
  if (!box) return;
  const list = heroList();
  if (!list.length) {
    box.innerHTML = '<div class="card muted">No hero matches that. The dropdown above searches everything else.</div>';
    return;
  }
  box.innerHTML = '<div class="grid">' + list.map(function (x) {
    const c = safeHex(x.color);
    const b = x.beginner || {};
    const src = x.iconLarge || x.icon || '';
    return '<button class="gcard" data-ent="' + esc(keyOf('heroes', x.id)) + '"' + (c ? ' style="--hc:' + c + '"' : '') + '>' +
      '<span class="gi"><img src="' + esc(src) + '" width="280" height="380" alt="" loading="lazy" onerror="dlSprErr(this)" /></span>' +
      '<span class="gb"><span class="gn">' + esc(x.name) + '</span>' +
      '<span class="gm"><span>' + esc(x.typeLabel || cap(x.type)) + '</span>' + (isNum(x.complexity) ? pipsHtml(x.complexity) : '') + '</span>' +
      '<span class="gd">' + esc(firstSentences(b.whatItIs, 2) || x.role || '') + '</span></span></button>';
  }).join('') + '</div>';
}

/* -------------------------------------------------------------- views: Items */

function renderItems() {
  const its = S.groups.items || [];
  const normal = its.filter(function (x) { return !x.streetBrawl; });
  const sbN = its.length - normal.length;
  const tiers = distinct(normal, 'tier').filter(isNum).sort(function (a, b) { return a - b; });
  let h = '<div class="view">';
  h += searchHtml('Search items and everything else');
  h += '<div class="chiprow">' +
    '<button class="fbtn' + (S.iSlot === 'all' ? ' on' : '') + '" data-islot="all">All ' + its.length + '</button>' +
    SLOT_ORDER.filter(function (s) { return its.some(function (x) { return x.slot === s; }); }).map(function (s) {
      const n = its.filter(function (x) { return x.slot === s; }).length;
      return '<button class="fbtn t-' + s + (S.iSlot === s ? ' on' : '') + '" data-islot="' + s + '">' + esc(SLOT_LABEL[s]) + ' ' + n + '</button>';
    }).join('') + '</div>';
  h += '<div class="chiprow">' +
    '<button class="fbtn' + (S.iTier === 'all' ? ' on' : '') + '" data-itier="all">Any tier</button>' +
    tiers.map(function (t) {
      return '<button class="fbtn' + (String(S.iTier) === String(t) ? ' on' : '') + '" data-itier="' + esc(t) + '">Tier ' + esc(t) +
        (tierCost(t) ? ' (' + esc(num(tierCost(t))) + ')' : '') + '</button>';
    }).join('') +
    (sbN ? '<button class="fbtn' + (S.iTier === 'sb' ? ' on' : '') + '" data-itier="sb">Street Brawl ' + sbN + '</button>' : '') + '</div>';
  h += '<div class="ctl"><button class="tbtn' + (S.iActive ? ' on' : '') + '" data-iactive>Only items with a button</button>' +
    '<label for="isort">Sort</label><select id="isort" class="sel">' +
    [['tier', 'Tier'], ['bought', 'Most bought'], ['az', 'A to Z']].map(function (o) {
      return '<option value="' + o[0] + '"' + (S.iSort === o[0] ? ' selected' : '') + '>' + o[1] + '</option>';
    }).join('') + '</select></div>';
  h += '<div id="listRegion"></div></div>';
  return h;
}

function itemList() {
  const qn = norm(S.q);
  const toks = qn ? qn.split(' ') : [];
  const list = (S.groups.items || []).filter(function (x) {
    if (S.iSlot !== 'all' && x.slot !== S.iSlot) return false;
    if (S.iTier === 'sb') { if (!x.streetBrawl) return false; }
    else if (S.iTier !== 'all' && (x.streetBrawl || String(x.tier) !== String(S.iTier))) return false;
    if (S.iActive && !x.isActive) return false;
    if (!toks.length) return true;
    const hay = norm([x.name, x.slot, 'tier ' + x.tier, words((x.shopFilters || []).join(' ')), x.streetBrawl ? 'street brawl' : '', firstSentences(x.text, 1)].join(' '));
    for (const t of toks) if (hay.indexOf(t) === -1) return false;
    return true;
  });
  list.sort(function (a, b) {
    if (S.iSort === 'bought') return (((b.perf && b.perf.matches) || 0) - ((a.perf && a.perf.matches) || 0)) || a.name.localeCompare(b.name);
    if (S.iSort === 'az') return a.name.localeCompare(b.name);
    const ta = a.streetBrawl ? 99 : (a.tier || 0), tb = b.streetBrawl ? 99 : (b.tier || 0);
    return (ta - tb) || (SLOT_ORDER.indexOf(a.slot) - SLOT_ORDER.indexOf(b.slot)) || a.name.localeCompare(b.name);
  });
  return list;
}

function fillItems() {
  const box = $('#listRegion');
  if (!box) return;
  const list = itemList();
  if (!list.length) {
    box.innerHTML = '<div class="card muted">No item matches that. The dropdown above searches everything else.</div>';
    return;
  }
  let h = '';
  let head = null;
  for (const it of list) {
    if (S.iSort === 'tier') {
      const label = it.streetBrawl ? 'Street Brawl only' : 'Tier ' + it.tier + (isNum(it.cost) ? ' - ' + num(it.cost) + ' souls' : '');
      if (label !== head) { head = label; h += '<h3 class="sh">' + esc(label) + '</h3>'; }
    }
    h += itemRow(it);
  }
  box.innerHTML = h;
}

/* ------------------------------------------------------------- views: Builds */

function loadAnalytics() {
  if (!S.analyticsP) {
    S.analyticsP = fetchJson('/island/apps/deadlock/data/analytics.json').catch(function (err) { S.analyticsP = null; throw err; });
  }
  return S.analyticsP;
}

function builtInBuildsBody() {
  const hs = (S.groups.heroes || []).slice().sort(function (a, b) { return a.name.localeCompare(b.name); });
  if (!hs.length) return '<div class="card">No hero data loaded.</div>';
  if (!S.bHero || !hero(S.bHero)) S.bHero = myHero() || hs[0].id;
  const hh = hero(S.bHero);
  let h = '<h3 class="sh">Starter builds</h3>';
  h += '<div class="ctl"><label for="bhero">Hero</label><select id="bhero" class="sel">' + hs.map(function (x) {
    return '<option value="' + esc(x.id) + '"' + (x.id === S.bHero ? ' selected' : '') + '>' + esc(x.name) + (x.id === myHero() ? ' (mine)' : '') + '</option>';
  }).join('') + '</select></div>';
  h += heroRow(hh, firstSentences((hh.beginner || {}).whatItIs, 1));
  const picks = starterPicks(hh);
  const t1 = tierCost(1), t2 = tierCost(2);
  if (picks.length) {
    h += '<p class="lede" style="margin:8px 2px">The cheap items' + (t1 && t2 ? ' (' + num(t1) + ' and ' + num(t2) + ' souls)' : '') +
      ' that ' + esc(hh.name) + ' players bought most often, with the games behind each number.</p>';
    for (const p of picks) h += itemBuyRow(p.t, p.it, hh);
  } else {
    h += '<div class="card muted">No starter picks could be worked out for this hero from the pulled data.</div>';
  }
  const note = dataWindowNote();
  if (note) h += '<div class="note">' + esc(note) + '</div>';
  h += '<div class="actrow"><button class="tbtn" data-ent="' + esc(keyOf('heroes', hh.id)) + '">Open ' + esc(hh.name) + '</button>' +
    '<button class="tbtn' + (myHero() === hh.id ? ' on' : '') + '" data-myhero="' + esc(hh.id) + '">' + (myHero() === hh.id ? 'My hero' : 'Make this my hero') + '</button></div>';
  h += '<h3 class="sh">Build generator</h3><div class="mount-slot" id="buildsMount">The goal-based generator (pick a hero, up to three goals, the enemy team and items you want to lock) ' +
    'is not in this version yet. When it is, it plugs into this tab and prints a receipt with a match count under every pick.</div>';
  return h;
}

function renderBuilds() {
  let h = '<div class="view">';
  h += searchHtml('Search anything while you plan');
  h += '<h2 class="vh">Builds</h2>';
  // The stamp and the ruling are the SHELL'S, rendered whichever body follows.
  h += stampHtml('buildsStamp', true);
  h += '<div class="ruling">Anything this tab recommends is the best it found in the numbers, not a proof that nothing better exists. Where a pick has no sample of matches behind it, it prints no number.</div>';
  let body = '';
  let external = false;
  if (window.DL_BUILDS && typeof window.DL_BUILDS.render === 'function') {
    try { body = String(window.DL_BUILDS.render() || ''); external = true; } catch (err) {
      body = '<div class="card">The build tool failed to start (' + esc(err && err.message ? err.message : err) + '). The starter builds below still work.</div>';
    }
  }
  if (!external) body += builtInBuildsBody();
  h += '<div id="buildsBody">' + body + '</div></div>';
  return h;
}

function afterBuildsRender() {
  if (window.DL_BUILDS && typeof window.DL_BUILDS.afterRender === 'function') {
    const root = $('#buildsBody');
    if (root) { try { window.DL_BUILDS.afterRender(root); } catch (err) { /* the tool owns its errors */ } }
  }
}

/* --------------------------------------------------------------- views: More */

function renderMore() {
  const m = S.meta || {};
  let h = '<div class="view">';
  h += searchHtml('Search anything in Deadlock');

  // Mechanics deep-dives.
  const mech = S.groups.mechanics || [];
  if (mech.length) {
    h += '<h2 class="vh">How the game works</h2>';
    h += '<p class="lede">' + mech.length + ' mechanics, each explained the same way: what it is, why it matters, when to use it.</p>';
    for (const c of distinct(mech, 'category')) {
      h += '<h3 class="sh">' + esc(c) + '</h3>';
      for (const e of mech.filter(function (x) { return x.category === c; })) {
        h += '<button class="rowcard" data-ent="' + esc(keyOf('mechanics', e.id)) + '"><span class="rb"><span class="rn">' + esc(e.name) +
          '</span><span class="rm">' + esc(firstSentences((e.beginner || {}).whatItIs, 1)) + '</span></span></button>';
      }
    }
  }

  // Map: the lanes the game data names.
  const lanes = (S.rules && S.rules.lanes) || [];
  if (lanes.length) {
    h += '<h3 class="sh">The map</h3><div class="card"><div class="lanes">' + lanes.map(function (l) {
      const rgb = Array.isArray(l.rgb) && l.rgb.length === 3 && l.rgb.every(isNum) ? 'rgb(' + l.rgb.join(',') + ')' : '';
      return '<span class="lane"' + (rgb ? ' style="--lc:' + rgb + '"' : '') + '><i></i>' + esc(l.name) + '</span>';
    }).join('') + '</div>' +
      '<p class="small muted" style="margin:8px 0 0">The game data names ' + lanes.length + ' lanes and colours them as shown. There is no map image here yet.' +
      (ent('mechanics:lanes-and-troopers') ? ' <button class="gl" data-ent="mechanics:lanes-and-troopers">How lanes work</button>' : '') + '</p></div>';
  }

  // Patch history.
  /* patches.updates is the merged list (forum changelog threads + Steam "Minor Update"
     posts that have no thread of their own), so the patch the data reflects is in it. */
  const pt = S.patches || {};
  const cur = patchInfo();
  const plist = (pt.updates || []).length ? pt.updates : (pt.forum || []);
  if (plist.length) {
    h += '<h3 class="sh">Patch history</h3><div class="card"><ul class="plist">' + plist.map(function (p) {
      const isCur = cur && ((p.guid && cur.guid === p.guid) || (p.title && cur.title === p.title));
      return '<li><span class="pd">' + esc(prettyDate(p.patchDate || p.date)) + '</span><span><a href="' + esc(p.link) + '" target="_blank" rel="noopener noreferrer">' +
        esc(p.postTitle || p.title) + '</a>' + (isCur ? ' <span class="cur">this data</span>' : '') + '</span></li>';
    }).join('') + '</ul><p class="small faint" style="margin:8px 0 0">Titles and dates of Valve\'s patch posts. Open one for the official patch text.</p></div>';
  }
  if ((pt.news || []).length) {
    h += '<h3 class="sh">News</h3><div class="card"><ul class="plist">' + pt.news.slice(0, 8).map(function (p) {
      return '<li><span class="pd">' + esc(prettyDate(p.date)) + '</span><span><a href="' + esc(p.link) + '" target="_blank" rel="noopener noreferrer">' + esc(p.title) + '</a></span></li>';
    }).join('') + '</ul></div>';
  }

  // Your saved data (profiles).
  h += '<h3 class="sh">Your profile</h3><div class="card">';
  h += '<div class="ctl" style="margin:0"><label for="prof">Profile</label><select id="prof" class="sel">' + Object.keys(ST.profiles).map(function (id) {
    return '<option value="' + esc(id) + '"' + (id === ST.active ? ' selected' : '') + '>' + esc(ST.profiles[id].name) + '</option>';
  }).join('') + '</select>' +
    '<button class="tbtn" data-newprof>New</button><button class="tbtn" data-renprof>Rename</button>' +
    (Object.keys(ST.profiles).length > 1 ? '<button class="tbtn danger" data-delprof>Delete</button>' : '') + '</div>';
  h += '<p class="small muted" style="margin:10px 0 0">Saved on this device only: your saved heroes and items, your hero, and the Start steps you ticked. ' +
    (myHero() ? 'Your hero: <b>' + esc(nameOf(hero(myHero()))) + '</b>.' : 'You have not picked a hero yet.') + '</p></div>';

  // Honesty surface: unresolved source conflicts.
  const claims = unresolvedClaims();
  if (claims.length) {
    h += '<h3 class="sh">What the sources disagree on</h3>';
    for (const c of claims) h += claimHtml(c);
  }

  h += '<h3 class="sh">Freshness</h3>' + stampHtml('moreStamp', true);

  /* Licence and attribution text lives ONCE, in the shell Attribution slot (registry attribution). This card lists sources by name and link only. */
  h += '<h3 class="sh">Where this comes from</h3><div class="card srcbox">';
  const srcs = m.sources || {};
  for (const key of Object.keys(srcs)) {
    const s = srcs[key];
    h += '<p style="margin:0 0 8px"><b>' + esc(s.name) + '</b><br />' +
      '<a href="' + esc(s.url) + '" target="_blank" rel="noopener noreferrer">' + esc(s.url) + '</a></p>';
  }
  h += '</div></div>';
  return h;
}

/* --------------------------------------------------------------- rendering */

const VIEWS = {
  start: renderStart, heroes: renderHeroes, items: renderItems,
  builds: renderBuilds, more: renderMore
};

function render() {
  const a = app();
  if (!a) return;
  const fn = VIEWS[S.view] || renderStart;
  a.innerHTML = fn();
  if (S.view === 'heroes') fillHeroes();
  if (S.view === 'items') fillItems();
  if (S.view === 'builds') afterBuildsRender();
  renderSuggest();
  const tabs = document.querySelectorAll('#tabbar .tab');
  for (let i = 0; i < tabs.length; i++) {
    const on = tabs[i].getAttribute('data-view') === S.view;
    tabs[i].classList.toggle('on', on);
    tabs[i].setAttribute('aria-current', on ? 'page' : 'false');
  }
}

function go(view) {
  S.notFound = false;
  if (!VIEWS[view]) view = 'start';
  if (S.view !== view) { S.view = view; S.q = ''; }
  render();
  try { window.scrollTo(0, 0); } catch (e) { /* no-op */ }
  setHash('#/' + view);
}

/* -------------------------------------------------------------- hash router */

/* The app owns the hash (registry nativeHashRouting: true). A hash WE wrote
   must not bounce back through applyHash, and a timer-based guard races the
   browser's own hashchange dispatch - so compare the value instead. */
let selfHash = null;
function setHash(h) {
  if (location.hash === h) return;
  selfHash = h;
  try { location.hash = h; } catch (e) { selfHash = null; }
}

function applyHash() {
  S.notFound = false;
  const raw = (location.hash || '').replace(/^#\/?/, '');
  const parts = raw.split('/').filter(Boolean);
  if (!parts.length) { S.view = 'start'; render(); return; }
  if (parts[0] === 'e' && parts.length >= 3) {
    const k = parts[1] + ':' + parts.slice(2).join(':');
    if (ent(k)) {
      const tab = tabOfGroup(parts[1]);
      if (S.view !== tab) S.view = VIEWS[tab] ? tab : 'more';
      render();
      openEntity(k);
      return;
    }
  }
  if (VIEWS[parts[0]]) { S.view = parts[0]; render(); return; }
  S.notFound = true;   // a link to a page that does not exist: Start shows a one-line notice
  S.view = 'start';
  render();
}

/* ------------------------------------------------------------------ events */

document.addEventListener('click', function (ev) {
  const t = ev.target;
  if (!t || !t.closest) return;

  if (t.closest('[data-close]')) { closeSheet(); return; }

  const entBtn = t.closest('[data-ent]');
  if (entBtn) { openEntity(entBtn.getAttribute('data-ent')); return; }

  const tab = t.closest('#tabbar .tab');
  if (tab) { if (sheetOpen) closeSheet(); go(tab.getAttribute('data-view')); return; }

  const goto = t.closest('[data-goto]');
  if (goto) { if (sheetOpen) closeSheet(); go(goto.getAttribute('data-goto')); return; }

  const ht = t.closest('[data-htype]');
  if (ht) { S.hType = ht.getAttribute('data-htype'); render(); return; }
  const hd = t.closest('[data-hdiff]');
  if (hd) { S.hDiff = hd.getAttribute('data-hdiff'); render(); return; }

  if (t.closest('[data-easy]')) {
    S.hDiff = String(minComplexity()); S.hType = 'all'; S.hSort = 'easy';
    go('heroes');
    return;
  }

  const isl = t.closest('[data-islot]');
  if (isl) { S.iSlot = isl.getAttribute('data-islot'); render(); return; }
  const itr = t.closest('[data-itier]');
  if (itr) { S.iTier = itr.getAttribute('data-itier'); render(); return; }
  if (t.closest('[data-iactive]')) { S.iActive = !S.iActive; render(); return; }

  if (t.closest('[data-clearq]')) { S.q = ''; render(); return; }

  const stp = t.closest('[data-step]');
  if (stp) { toggleStep(stp.getAttribute('data-step')); render(); return; }

  const pin = t.closest('[data-pin]');
  if (pin) {
    const k = pin.getAttribute('data-pin');
    const on = togglePin(k);
    pin.classList.toggle('on', on);
    pin.textContent = on ? 'Saved' : 'Save';
    return;
  }

  const mh = t.closest('[data-myhero]');
  if (mh) {
    const id = mh.getAttribute('data-myhero');
    setMyHero(myHero() === id ? null : id);
    const on = myHero() === id;
    mh.classList.toggle('on', on);
    mh.textContent = on ? 'My hero' : 'Make this my hero';
    return;
  }

  if (t.closest('[data-newprof]')) {
    const nm = window.prompt('Name this profile', 'Profile ' + (Object.keys(ST.profiles).length + 1));
    if (nm) {
      const id = 'p' + Date.now().toString(36);
      ST.profiles[id] = blankProfile(nm.slice(0, 40));
      ST.active = id;
      saveState();
      render();
    }
    return;
  }
  if (t.closest('[data-renprof]')) {
    const nm = window.prompt('Rename this profile', prof().name);
    if (nm) { prof().name = nm.slice(0, 40); saveState(); render(); }
    return;
  }
  if (t.closest('[data-delprof]')) {
    if (Object.keys(ST.profiles).length > 1 && window.confirm('Delete "' + prof().name + '"?')) {
      delete ST.profiles[ST.active];
      ST.active = Object.keys(ST.profiles)[0];
      saveState();
      render();
    }
    return;
  }
});

document.addEventListener('input', function (ev) {
  const t = ev.target;
  if (t && t.id === 'q') {
    S.q = t.value || '';
    if (S.view === 'heroes') fillHeroes();
    if (S.view === 'items') fillItems();
    renderSuggest();
  }
});

document.addEventListener('change', function (ev) {
  const t = ev.target;
  if (!t) return;
  if (t.id === 'prof' && ST.profiles[t.value]) { ST.active = t.value; saveState(); render(); return; }
  if (t.id === 'hsort') { S.hSort = t.value; fillHeroes(); return; }
  if (t.id === 'isort') { S.iSort = t.value; fillItems(); return; }
  if (t.id === 'bhero') { S.bHero = t.value; render(); return; }
});

document.addEventListener('keydown', function (ev) {
  if (ev.key === 'Escape' && sheetOpen) { closeSheet(); return; }
  if (ev.key === 'Enter' && ev.target && ev.target.id === 'q') {
    /* On Heroes / Items the grid filters inline, so Enter opens the single match there;
       everywhere else (and when the grid has none) it opens the first dropdown row. */
    const inline = S.view === 'heroes' ? heroList() : S.view === 'items' ? itemList() : [];
    if (inline.length === 1) {
      ev.preventDefault();
      openEntity(keyOf(S.view, inline[0].id));
      return;
    }
    const first = inline.length ? null : document.querySelector('#suggest .sug-row');
    if (first) { ev.preventDefault(); openEntity(first.getAttribute('data-ent')); }
  }
});

window.addEventListener('hashchange', function () {
  if (selfHash !== null && location.hash === selfHash) { selfHash = null; return; }
  selfHash = null;
  if (!S.booted) return;
  if (sheetOpen) {
    const sh = $('#sheet');
    if (sh) sh.hidden = true;
    sheetOpen = false;
    try { document.body.style.overflow = ''; } catch (e) { /* no-op */ }
  }
  applyHash();
});

/* -------------------------------------------------------------------- boot */

function fetchJson(path) {
  return fetch(path, { cache: 'no-cache' }).then(function (r) {
    if (!r.ok) throw new Error(path + ' -> HTTP ' + r.status);
    return r.json();
  });
}

function boot() {
  ST = loadState();
  const a = app();
  if (a) a.innerHTML = '<div class="boot">Loading Deadlock data...</div>';

  fetchJson('/island/apps/deadlock/data/meta.json').then(function (meta) {
    S.meta = meta;
    const gr = meta.groups || {};
    S.gmeta = Object.keys(gr).map(function (k) {
      return {
        key: k, label: gr[k].label || cap(k), singular: gr[k].singular || cap(k), file: gr[k].file || (k + '.json'),
        layout: gr[k].layout || 'pages', parent: gr[k].parent || null, tab: gr[k].tab || null
      };
    });
    if (!S.gmeta.length) throw new Error('meta.json has no groups map');
    for (const d of S.gmeta) S.gmap[d.key] = d;
    for (const d of S.gmeta) {
      let tab = d.tab ? String(d.tab).toLowerCase() : null;
      if (!tab && d.parent && S.gmap[d.parent] && S.gmap[d.parent].tab) tab = String(S.gmap[d.parent].tab).toLowerCase();
      S.tabOf[d.key] = tab && VIEW_NAMES.indexOf(tab) !== -1 ? tab : 'more';
    }
    const optional = function (file) { return fetchJson('/island/apps/deadlock/data/' + file).catch(function () { return null; }); };
    return Promise.all(S.gmeta.map(function (d) {
      return fetchJson('/island/apps/deadlock/data/' + d.file).then(function (rows) {
        S.groups[d.key] = Array.isArray(rows) ? rows : [];
      });
    }).concat([
      optional('patches.json').then(function (p) { S.patches = p; }),
      optional('rules.json').then(function (r) { S.rules = r; })
    ]));
  }).then(function () {
    for (const d of S.gmeta) {
      for (const e of S.groups[d.key]) S.byId[keyOf(d.key, e.id)] = e;
    }
    for (const x of (S.groups.abilities || [])) {
      (S.abByHero[x.hero] = S.abByHero[x.hero] || []).push(x);
    }
    for (const id of Object.keys(S.abByHero)) S.abByHero[id].sort(function (p, q) { return p.slot - q.slot; });
    buildGlossaryLinker();
    buildIndex();
    /* The pill's static text is lifted by the assembler at build time (registry
       stamp.fromHtmlId); this keeps it true when the app runs standalone, and
       app/check-app.mjs asserts the static text still names meta.patch.title. */
    const pill = $('#patchPill');
    if (pill && S.meta.patch && S.meta.patch.title) pill.textContent = 'Patch ' + S.meta.patch.title;
    const foot = $('#footNote');
    if (foot && S.meta.attribution) foot.textContent = S.meta.attribution;
    renderPreBanner();
    S.booted = true;
    applyHash();
    warmSprites();
  }).catch(function (err) {
    const el = app();
    if (el) {
      el.innerHTML = '<div class="boot err">Could not load the Deadlock dataset.<br />' +
        esc(err && err.message ? err.message : String(err)) +
        '<br /><span class="small faint">If you are offline and this app was never opened online, there is nothing cached yet.</span></div>';
    }
  });
}

/* ---------------------------------------------------------- the stable API */

window.DL_APP = {
  S: S, esc: esc, num: num, pct: pct, ent: ent, iconHtml: iconHtml, openEntity: openEntity,
  prof: prof, ovGet: ovGet, ovSet: ovSet, saveState: saveState, myHero: myHero,
  loadAnalytics: loadAnalytics, rerender: render, firstSentences: firstSentences,
  prettyDate: prettyDate, searchHtml: searchHtml
};

/* ------------------------------------------------------ offline sprite warm */
/* Every entity icon is a LOCAL file under sprites/ (heroes, abilities, items),
   but LOCAL is not CACHED. The shell's service worker stores an image the
   moment something requests it and not a moment before, so an installed PWA
   would hold only the icons the viewer had already scrolled past, and offline
   the rest would draw the '?' tile. registry.spriteWarm gives this route its
   own cache bucket, cache-first and exempt from the shared image LRU's
   2,000-entry cap - but that is only half of it: the bucket pre-fetches
   nothing. This is the other half: the app names the files, the worker does
   the caching.

   The APP owns the list because only the app has data/*.json parsed. It posts
   paths RELATIVE TO the sprites dir (heroes/x.webp, items/y.webp, ...) in the
   generic single-tier shape (tiers: [['icons', files]]); the worker resolves
   them against its own sprite dir and fetches 24 at a time in the background,
   writing a completion marker keyed to `stamp`, so it runs once per dataset. */

/* Two path shapes reach us and both must reduce to the part after sprites/:
     standalone  sprites/heroes/abrams-sm.webp              (what data/*.json ships)
     mounted     (shell base)/apps/deadlock/sprites/heroes/...  (assemble rewrites it)
   Strip through the FIRST sprites/ segment - a path with no such segment is
   quarantined into `unresolved` and never posted, so a new path shape shows up
   as an empty warm rather than as ~437 silently-404ing requests. */
function spriteRel(p) {
  const s = String(p == null ? '' : p);
  const i = s.search(/sprites\//);
  return i === -1 ? '' : s.slice(i + 8);
}

let SPRITE_WARM = null;
function spriteWarmPayload() {
  if (SPRITE_WARM) return SPRITE_WARM;
  const files = new Set(), bad = new Set();
  for (const d of S.gmeta) {
    for (const e of (S.groups[d.key] || [])) {
      if (!e) continue;
      for (const src of [e.icon, e.iconLarge]) {
        if (!src) continue;
        const f = spriteRel(src);
        if (!f || f.charAt(0) === '/') { bad.add(String(src)); continue; }
        files.add(f);
      }
    }
  }
  const m = S.meta || {};
  SPRITE_WARM = {
    files: Array.from(files),
    unresolved: Array.from(bad),
    // Changes whenever the dataset is re-pulled, which is what re-warms new sprites.
    stamp: (m.pulledAt || '') + ':' + ((m.sprites && m.sprites.present) || 0) + ':' + files.size
  };
  return SPRITE_WARM;
}

/* boot()'s data fetch and the service-worker handshake race each other, so
   BOTH sides call this and it no-ops until both halves are ready. Whichever
   finishes last is the one that actually posts. */
let SW_TARGET = null;
function warmSprites() {
  if (!SW_TARGET || !S.booted) return;
  try {
    const p = spriteWarmPayload();
    if (!p.files.length) return;
    SW_TARGET.postMessage({ type: 'warm-sprites', stamp: p.stamp, tiers: [['icons', p.files]] });
  } catch (e) { /* no-op */ }
}
if ('serviceWorker' in navigator) {
  /* This app still REGISTERS nothing - the shell owns exactly one worker (see
     the PORT NOTES at the top of this file). It only waits for whichever
     worker already controls this page. Served standalone with no worker at
     all, `ready` never settles and this is simply a no-op. */
  navigator.serviceWorker.ready.then(function (reg) {
    SW_TARGET = navigator.serviceWorker.controller || (reg && reg.active);
    warmSprites();
  }).catch(function () { /* no-op */ });
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
